<style>
:root{--navy:#111b3c;--navy2:#17264e;--blue:#5268f5;--blue2:#6f80ff;--ink:#17213c;--muted:#78829b;--line:#e8ebf4;--bg:#f5f7fc;--white:#fff;--green:#1aaf83;--orange:#f3a43b;--red:#e46c73;--purple:#9775e8;--shadow:0 8px 28px rgba(22,35,78,.07)}
