@media(max-width:1150px){.sidebar{width:220px}.main{margin-left:220px;width:calc(100% - 220px)}.content{padding:26px 24px}.topbar{padding:0 24px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.layout2{grid-template-columns:1fr}.coursegrid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.sidebar{width:72px;padding:20px 9px}.brand{padding:0 7px 24px}.brandmark{width:42px;height:42px;flex-shrink:0}.brandtext,.navlabel,.nav span:not(.ico),.navcount,.helpbox,.usermini>div:not(.avatar){display:none}.nav{justify-content:center;padding:12px 8px}.nav .ico{width:auto;font-size:19px}.usermini{justify-content:center;padding:15px 0 0}.main{margin-left:72px;width:calc(100% - 72px)}.topbar{height:65px;padding:0 13px}.topright{gap:7px}.search{display:none}.profilebtn strong,.profilebtn small{display:none}.profilebtn .avatar{width:34px;height:34px}.content{padding:23px 14px}.welcome{display:block}.welcome h1{font-size:23px}.welcome .actions{margin-top:16px}.stats{gap:10px}.stat{padding:14px}.statnum{font-size:24px}.stathead{font-size:10px}.coursegrid{grid-template-columns:1fr}.pagehead{display:block}.pagehead .btn{margin-top:13px}.layout2,.detailgrid{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}.field.full{grid-column:auto}.rolemenu>button{font-size:0;padding:9px}.rolemenu>button:after{content:'Vai trò';font-size:11px}.panel{padding:16px}.topright .iconbtn{width:33px;height:33px}.task{gap:8px}.task .pill{display:none}}

.backend-status{display:inline-flex;align-items:center;gap:6px;margin-left:12px;padding:4px 8px;border:1px solid #dfe5ef;border-radius:999px;background:#f8fafc;color:#55627a;font-size:11px;font-weight:700;vertical-align:middle;white-space:nowrap}.backend-status .status-dot{width:7px;height:7px;border-radius:50%;background:#b7791f;display:inline-block;flex:0 0 7px}.backend-status.online{border-color:#bfe7d7;background:#effaf5;color:#17684f}.backend-status.online .status-dot{background:#16956e}.backend-status.offline{border-color:#f0d4ad;background:#fff9f0;color:#8a5415}.backend-status.offline .status-dot{background:#c07a1c}
@media(max-width:760px){.backend-status .status-text{display:none}.backend-status{margin-left:4px;padding:4px 6px}.crumb{min-width:0;max-width:48%;overflow:hidden;text-overflow:ellipsis}.topbar{gap:8px}}
/* UI UX Pro Max-inspired refinement: focused education dashboard, semantic tokens, readable density. */
:root{
  --navy:#172344;--navy2:#1b2d53;--blue:#4056d6;--blue2:#6375e9;
  --ink:#18243d;--muted:#59657c;--line:#e2e7f0;--bg:#f5f7fb;--white:#fff;
  --green:#157b5c;--orange:#9b5c0b;--red:#b42332;--purple:#7651b5;
  --shadow:0 8px 28px rgba(22,35,78,.075);--radius-card:16px;
}
html{scroll-behavior:smooth;scroll-padding-top:92px}
body{font-size:15px;line-height:1.55;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased}
button,input,select,textarea{font:inherit}
button{touch-action:manipulation}
.skip-link{position:fixed;left:14px;top:-60px;z-index:2000;background:#fff;color:#172344;border:2px solid var(--blue);border-radius:9px;padding:10px 14px;font-weight:700;box-shadow:var(--shadow)}
.skip-link:focus{top:12px}
:focus-visible{outline:3px solid #7d8bff!important;outline-offset:3px!important}
.sidebar{background:var(--navy);border-right:1px solid #26375c}
.brandmark{background:var(--blue);box-shadow:none;border-radius:12px}
.brand small{font-size:11px;letter-spacing:.08em}
.navlabel{font-size:11px;letter-spacing:1.1px;color:#b0bddc}
.nav{min-height:46px;font-size:14px;gap:12px;border:1px solid transparent;transition:background .16s ease,color .16s ease,border-color .16s ease}
.nav .ico{width:22px;height:22px;display:grid;place-items:center;flex:0 0 22px}
.nav .ico svg,.iconbtn svg{width:19px;height:19px;display:block;fill:none;stroke:currentColor;stroke-width:1.75;stroke-linecap:round;stroke-linejoin:round}
.nav:hover{background:#26365a;color:#fff}
.nav.active{background:#4056d6;border-color:#7181ec;box-shadow:none;color:#fff}
.nav .navcount{font-size:11px;min-width:24px;text-align:center;background:#f4cc82;color:#402c0d}
.helpbox{border-radius:14px;background:#1d2d50;border-color:#344365}
.helpbox .bulb{display:flex;color:#c3cdfa}
.helpbox p{font-size:12px;color:#d0d8ec}
.helpbox strong,.usermini strong{font-size:13px}
.usermini small{font-size:12px;color:#c9d2e7}
.main{min-width:0}
.topbar{padding-inline:clamp(16px,2.5vw,36px);background:rgba(255,255,255,.96);backdrop-filter:blur(10px);gap:18px}
.crumb{font-size:13px;color:#59657c;white-space:nowrap}
.topright{gap:12px;min-width:0}
.search input{width:clamp(190px,20vw,290px);font-size:14px;min-height:42px;color:var(--ink);background:#f7f8fc;border-color:#dfe4ef}
.search:before{content:"";width:10px;height:10px;border:1.7px solid #69758d;border-radius:50%;top:14px;left:13px;font-size:0}
.search:after{content:"";width:5px;height:1.7px;position:absolute;left:23px;top:25px;background:#69758d;border-radius:2px;transform:rotate(45deg)}
.iconbtn{min-width:42px;min-height:42px;width:42px;height:42px;display:grid;place-items:center}
.rolemenu>button{min-height:42px;border:1px solid #dfe4ef;background:#fff;border-radius:10px;padding:9px 12px;display:flex;gap:8px;align-items:center;color:#35415c;font-size:13px;font-weight:700}
.rolemenu>button:hover{background:#f7f8ff;border-color:#b7c1ed}
.profilebtn{min-height:44px;border-radius:10px;padding:3px 5px}
.profilebtn:hover{background:#f6f7fc}
.profilebtn strong{font-size:13px}
.profilebtn small{font-size:12px;color:var(--muted)}
.content{max-width:1540px;padding:clamp(20px,2.5vw,36px) clamp(16px,2.5vw,36px) 48px}
.welcome{align-items:center;gap:24px;margin-bottom:26px}
.eyebrow{font-size:11px;letter-spacing:1.25px;margin-bottom:8px}
.welcome h1{font-size:clamp(25px,2vw,32px);letter-spacing:-.8px;line-height:1.25}
.welcome p{font-size:14px;line-height:1.65;max-width:700px}
.btn{font-size:13px;min-height:42px;padding:9px 14px;border-radius:10px;transition:background .16s ease,border-color .16s ease,box-shadow .16s ease,transform .16s ease}
.btn:hover{transform:translateY(-1px)}
.btn.primary{background:var(--blue);border-color:var(--blue);box-shadow:0 4px 10px #4056d61a}
.btn.primary:hover{background:#3045bf;border-color:#3045bf}
.btn.soft{background:#edf0ff;border-color:#dce2ff;color:#3448bd}
.stats{gap:16px;margin-bottom:22px}
.stat{border-color:#e4e9f2;border-radius:var(--radius-card);padding:20px;box-shadow:0 2px 8px rgba(20,35,70,.025)}
.stathead{font-size:12px;color:#526079}
.staticon{border-radius:10px;font-size:16px}
.statnum{font-size:clamp(25px,2vw,30px);letter-spacing:-.7px;margin:9px 0 5px}
.statfoot{font-size:12px;line-height:1.45;color:#59657c}
