<script>
// Attach Laravel's CSRF token to unsafe same-origin requests and refresh it after logout.
(() => {
  const nativeFetch = window.fetch.bind(window);
  window.fetch = async (input, init = {}) => {
    const method = String(init.method || 'GET').toUpperCase();
    const headers = new Headers(init.headers || {});
    if (!headers.has('Accept')) headers.set('Accept', 'application/json');
    const tokenMeta = document.querySelector('meta[name="csrf-token"]');
    if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && tokenMeta?.content) {
      headers.set('X-CSRF-TOKEN', tokenMeta.content);
    }
    const response = await nativeFetch(input, { ...init, headers, credentials: init.credentials || 'same-origin' });
    if ((response.headers.get('content-type') || '').includes('application/json')) {
      try {
        const payload = await response.clone().json();
        if (payload.csrfToken && tokenMeta) tokenMeta.content = payload.csrfToken;
      } catch (_) { /* Not every JSON endpoint needs to return a CSRF token. */ }
    }
    return response;
  };
})();
</script>

