<script>
const seed={"users":[{"id":1,"name":"Nguyễn An Khang","code":"2380600984","email":"khang.nguyen@hutech.edu.vn","role":"student","status":"Hoạt động"},{"id":2,"name":"Phạm Dương Đình Huy","code":"2380600870","email":"huy.pham@hutech.edu.vn","role":"student","status":"Hoạt động"},{"id":3,"name":"Lê Phương Nam","code":"2380614933","email":"nam.le@hutech.edu.vn","role":"student","status":"Hoạt động"},{"id":4,"name":"Trần Minh Anh","code":"GV001","email":"minhanh@hutech.edu.vn","role":"teacher","status":"Hoạt động"},{"id":5,"name":"Quản trị viên","code":"ADMIN01","email":"admin@elearn.local","role":"admin","status":"Hoạt động"},{"id":6,"name":"Võ Hoàng Yến","code":"2380601122","email":"yen.vo@hutech.edu.vn","role":"student","status":"Hoạt động"},{"id":7,"name":"Nguyễn Quốc Bảo","code":"GV002","email":"quocbao@hutech.edu.vn","role":"teacher","status":"Hoạt động"},{"id":8,"name":"Lê Thu Hà","code":"GV003","email":"thuha@hutech.edu.vn","role":"teacher","status":"Hoạt động"}],"courses":[{"id":1,"code":"CSDLNC-01","name":"Cơ sở dữ liệu nâng cao","teacher":"Trần Minh Anh","teacherId":4,"term":"Học kỳ 1 · 2026–2027","students":36,"progress":68,"color":"cover1","symbol":"DB","category":"Cơ sở dữ liệu","description":"Thiết kế cơ sở dữ liệu quan hệ, phụ thuộc hàm, chuẩn hóa, ràng buộc toàn vẹn và truy vấn SQL nâng cao.","lessons":[{"id":1,"title":"Tổng quan hệ quản trị cơ sở dữ liệu","duration":"18 phút","type":"Video bài giảng"},{"id":2,"title":"Phụ thuộc hàm và khóa","duration":"25 phút","type":"Tài liệu + video"},{"id":3,"title":"Chuẩn hóa dữ liệu","duration":"32 phút","type":"Video bài giảng"},{"id":4,"title":"Ràng buộc toàn vẹn","duration":"20 phút","type":"Tài liệu PDF"}]},{"id":2,"code":"WEB-02","name":"Lập trình ứng dụng Web","teacher":"Nguyễn Quốc Bảo","teacherId":7,"term":"Học kỳ 1 · 2026–2027","students":42,"progress":42,"color":"cover2","symbol":"</>","category":"Phát triển phần mềm","description":"Nền tảng phát triển ứng dụng web, xử lý phía máy chủ, giao diện và kết nối cơ sở dữ liệu.","lessons":[{"id":5,"title":"Kiến trúc ứng dụng web","duration":"22 phút","type":"Video bài giảng"},{"id":6,"title":"Form và xử lý dữ liệu","duration":"28 phút","type":"Thực hành"}]},{"id":3,"code":"ATUD-01","name":"An toàn ứng dụng","teacher":"Trần Minh Anh","teacherId":4,"term":"Học kỳ 1 · 2026–2027","students":31,"progress":85,"color":"cover3","symbol":"⌑","category":"An toàn thông tin","description":"Nhận diện lỗ hổng ứng dụng, kiểm soát truy cập và các nguyên tắc xây dựng phần mềm an toàn.","lessons":[{"id":7,"title":"Mô hình đe dọa","duration":"23 phút","type":"Video bài giảng"},{"id":8,"title":"Kiểm soát truy cập","duration":"19 phút","type":"Tài liệu"}]},{"id":4,"code":"PTPM-03","name":"Phân tích và thiết kế phần mềm","teacher":"Lê Thu Hà","teacherId":8,"term":"Học kỳ 1 · 2026–2027","students":28,"progress":25,"color":"cover4","symbol":"◇","category":"Phân tích thiết kế","description":"Phân tích yêu cầu, mô hình hóa hệ thống, thiết kế kiến trúc và tổ chức triển khai dự án phần mềm.","lessons":[{"id":9,"title":"Thu thập yêu cầu","duration":"20 phút","type":"Video bài giảng"},{"id":10,"title":"Mô hình Use Case","duration":"24 phút","type":"Tài liệu"}]}],"assignments":[{"id":1,"courseId":1,"title":"Bài tập 01: Phụ thuộc hàm","type":"Bài tập cá nhân","due":"2026-10-13","points":10,"status":"Chưa nộp","submissions":[],"description":"Xác định khóa ứng viên, phủ tối thiểu và phân tích phụ thuộc hàm cho lược đồ quan hệ đã cho."},{"id":2,"courseId":1,"title":"Thiết kế ERD hệ thống thực tế","type":"Bài tập nhóm","due":"2026-10-16","points":10,"status":"Đã nộp","submissions":[{"userId":1,"submitted":"2026-10-09","answer":"Bản ERD và mô tả nghiệp vụ nhóm 3cayxanh.","score":null,"feedback":""}],"description":"Xây dựng mô hình ERD cho một hệ thống thông tin thực tế, giải thích khóa và lực lượng quan hệ."},{"id":3,"courseId":2,"title":"Thực hành Form và CRUD","type":"Bài thực hành","due":"2026-10-18","points":10,"status":"Chưa nộp","submissions":[],"description":"Xây dựng biểu mẫu thêm, sửa, xóa dữ liệu và kiểm tra dữ liệu đầu vào."},{"id":4,"courseId":3,"title":"Phân tích rủi ro ứng dụng","type":"Bài tập nhóm","due":"2026-10-20","points":10,"status":"Đã chấm","submissions":[{"userId":1,"submitted":"2026-10-05","answer":"Báo cáo phân tích rủi ro phiên bản 1.","score":8.5,"feedback":"Phân tích rõ ràng. Cần bổ sung biện pháp xác minh."}],"description":"Phân tích ba rủi ro bảo mật và đề xuất biện pháp giảm thiểu."},{"id":5,"courseId":1,"title":"Kiểm tra chương 1: Mô hình quan hệ","type":"Trắc nghiệm","due":"2026-10-22","points":10,"status":"Chưa mở","submissions":[],"description":"Bài kiểm tra ngắn về mô hình quan hệ, khóa và ràng buộc."}],"grades":[{"userId":1,"courseId":1,"work":"Bài thực hành 0","score":9,"max":10,"feedback":"Trình bày tốt."},{"userId":1,"courseId":3,"work":"Bài tập phân tích rủi ro","score":8.5,"max":10,"feedback":"Bổ sung phần xác minh."},{"userId":2,"courseId":1,"work":"Bài thực hành 0","score":8,"max":10,"feedback":"Đạt yêu cầu."},{"userId":3,"courseId":1,"work":"Bài thực hành 0","score":9.5,"max":10,"feedback":"Tốt."}],"enrollments":[{"courseId":1,"studentId":1,"progress":68},{"courseId":1,"studentId":2,"progress":72},{"courseId":1,"studentId":3,"progress":78},{"courseId":1,"studentId":6,"progress":44},{"courseId":2,"studentId":1,"progress":42},{"courseId":2,"studentId":6,"progress":30},{"courseId":3,"studentId":1,"progress":85},{"courseId":4,"studentId":2,"progress":25}]};
let db=JSON.parse(JSON.stringify(seed));
let role='student',sessionUser=null,page='dashboard',currentCourse=null,toastTimer,lastFocusedElement=null;
const roleInfo={student:{name:'Nguyễn An Khang',initial:'NK',label:'Sinh viên',identifier:'khang.nguyen@hutech.edu.vn'},teacher:{name:'Trần Minh Anh',initial:'MA',label:'Giảng viên',identifier:'minhanh@hutech.edu.vn'},admin:{name:'Quản trị viên',initial:'AD',label:'Quản trị viên',identifier:'admin@elearn.local'}};
let backendConnected=false,saveChain=Promise.resolve();
function updateBackendStatus(online,detail){backendConnected=!!online;const el=document.getElementById('backendStatus');if(!el)return;el.classList.toggle('online',backendConnected);el.classList.toggle('offline',!backendConnected);const label=el.querySelector('.status-text');if(label)label.textContent=detail||(backendConnected?'Đã kết nối MySQL':'Chưa kết nối máy chủ');el.title=backendConnected?'Dữ liệu được xác thực và lưu qua API vào MySQL trên máy chủ demo.':'Chưa kết nối backend E-Learn.'}
function showLoginScreen(message=''){document.getElementById('appShell').hidden=true;document.getElementById('loginScreen').hidden=false;document.getElementById('loginError').textContent='';const notice=document.getElementById('loginOfflineNotice');if(message){notice.textContent=message;notice.style.display='block'}else{notice.textContent='';notice.style.display='none'}}
function save(){
  if(!sessionUser){showLoginScreen('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');return}
  const snapshot=JSON.stringify(db);
  saveChain=saveChain.catch(()=>{}).then(()=>fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:snapshot})).then(async r=>{const data=await r.json();if(!r.ok){if(r.status===401){sessionUser=null;showLoginScreen('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.')}const err=new Error(data.error||'Không lưu được dữ liệu');err.status=r.status;throw err}if(data.state)db=data.state;updateBackendStatus(true,'Đã lưu MySQL')}).catch(async err=>{updateBackendStatus(false,err.status===403?'Thao tác bị từ chối':'Lỗi lưu dữ liệu');if(err.status!==401)showToast(err.message||'Không thể lưu dữ liệu.');try{const r=await fetch('/api/state',{cache:'no-store',credentials:'same-origin'});if(r.ok){db=await r.json();render()}}catch(_){}});
}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function userById(id){return db.users.find(u=>u.id===id)||{name:'Người dùng',role:'student'}}
function currentUser(){return sessionUser||roleInfo[role]}
function initials(n){return n.split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase()}
function fmtDate(d){if(!d)return 'Chưa đặt hạn';return new Date(d+'T00:00:00').toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'})}
function roleLabel(r){return {student:'Sinh viên',teacher:'Giảng viên',admin:'Quản trị viên'}[r]||r}
function courseById(id){return db.courses.find(c=>c.id===id)||db.courses[0]}
function nextRecordId(items){const ids=(items||[]).map(x=>Number(x.id)+1).filter(Number.isFinite);return Math.max(Date.now(),0,...ids)}
function tasksForUser(){return db.assignments.filter(a=>role==='teacher'?courseById(a.courseId).teacherId===sessionUser?.id:true)}
function toggleRoleMenu(){let menu=document.getElementById('roleOptions'),button=document.querySelector('.rolemenu>button');let open=!menu.classList.contains('open');menu.classList.toggle('open',open);button?.setAttribute('aria-expanded',String(open))}
async function setRole(r){document.getElementById('roleOptions').classList.remove('open');document.querySelector('.rolemenu>button')?.setAttribute('aria-expanded','false');await saveChain.catch(()=>{});await loginAsDemo(r)}
async function loginAsDemo(r){const account=roleInfo[r];if(!account)return;try{if(sessionUser)await fetch('/api/logout',{method:'POST',credentials:'same-origin'});const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({identifier:account.identifier,password:'Demo123!'})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Không đăng nhập được');await loadAuthenticatedApp(result.user);showToast('Đã đăng nhập: '+roleLabel(result.user.role)+'.')}catch(err){showLoginScreen('Không thể đăng nhập. Hãy kiểm tra backend và tài khoản demo.');document.getElementById('loginError').textContent=err.message||'Đăng nhập thất bại.'}}
function showToast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function closeModal(){let back=document.getElementById('modalBack');back.classList.remove('show');if(lastFocusedElement&&lastFocusedElement.isConnected){lastFocusedElement.focus()}lastFocusedElement=null}
function showModal(title,sub,body,buttons){lastFocusedElement=document.activeElement;document.getElementById('modalTitle').textContent=title;document.getElementById('modalSub').textContent=sub||'';document.getElementById('modalBody').innerHTML=body;document.getElementById('modalFoot').innerHTML=buttons||'<button class="btn" onclick="closeModal()">Đóng</button>';document.getElementById('modalBack').classList.add('show');setTimeout(()=>{document.querySelector('#modalBack .close, #modalBack input, #modalBack textarea, #modalBack select, #modalBack button')?.focus()},0)}
function field(label,name,placeholder='',type='text',value='',full=false){let id='field_'+name;return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label><input id="${id}" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" required></div>`}
function areaField(label,name,placeholder='',full=true){let id='field_'+name;return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label><textarea id="${id}" name="${name}" placeholder="${placeholder}" required></textarea></div>`}
function selectField(label,name,options,full=false){let id='field_'+name;return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label><select id="${id}" name="${name}">${options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select></div>`}
function roleTag(r){let c=r==='admin'?'red':r==='teacher'?'blue':'green';return `<span class="pill ${c}">${roleLabel(r)}</span>`}
function statusTag(s){let c=s==='Đã nộp'||s==='Đã chấm'?'green':s==='Chưa mở'?'gray':s==='Quá hạn'?'red':'orange';return `<span class="pill ${c}">${esc(s)}</span>`}
function statCard(label,num,icon,bg,color,foot){let key=label.includes('người dùng')||label==='Sinh viên'?'users':label.includes('Điểm')||label.includes('điểm')?'grade':label.includes('Tiến độ')||label.includes('hoàn thành')?'progress':label.includes('Bài tập')||label.includes('Bài cần chấm')?'task':'course';let paths={users:'<path d="M16 20v-1.5a4.5 4.5 0 0 0-4.5-4.5h-3A4.5 4.5 0 0 0 4 18.5V20"/><circle cx="10" cy="7" r="3.5"/><path d="M16 4.5a3.5 3.5 0 0 1 0 6.8M18 14.5a4.5 4.5 0 0 1 2 4V20"/>',grade:'<path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9Z"/>',progress:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7v5l3 2"/>',task:'<path d="M8 4H5a2 2 0 0 0-2 2v13h16a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-3"/><rect x="8" y="2.5" width="8" height="4" rx="1"/><path d="m8 13 2.2 2.2L15.5 10"/>',course:'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21z"/><path d="M4 5.5V21M8 7h8M8 11h8"/>'};return `<div class="stat"><div class="stathead"><span>${label}</span><span class="staticon" style="background:${bg};color:${color}"><svg viewBox="0 0 24 24" aria-hidden="true">${paths[key]}</svg></span></div><div class="statnum">${num}</div><div class="statfoot">${foot}</div></div>`}
function courseCard(c){return `<article class="coursecard" role="button" tabindex="0" aria-label="Mở khóa học ${esc(c.name)}" onclick="openCourse(${c.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openCourse(${c.id})}"><div class="coursecover ${c.color||'cover1'}"><span class="tag">${esc(c.category||'Khóa học')}</span><span class="symbol">${esc(c.symbol||'✦')}</span></div><div class="coursebody"><h3>${esc(c.name)}</h3><div class="coursemeta"><span class="metaitem"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3.5"/><path d="M2.5 20c.3-3.5 2.5-5.5 6.5-5.5s6.2 2 6.5 5.5"/></svg>${esc(c.teacher)}</span><span class="metaitem"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21z"/><path d="M4 5.5V21"/></svg>${c.students} học viên</span></div><div class="progress"><span style="width:${Math.min(100,c.progress||0)}%"></span></div><div class="progressinfo"><span>Tiến độ học tập</span><b>${c.progress||0}%</b></div></div></article>`}
function courseList(){return role==='teacher'?db.courses.filter(c=>c.teacherId===sessionUser?.id):db.courses}
function assignmentCards(limit=4){let arr=tasksForUser().slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,limit);return arr.map(a=>`<div class="task"><div class="taskicon" style="background:${a.status==='Đã nộp'?'#e3f7ef':a.status==='Đã chấm'?'#fff2de':'#eef0ff'};color:${a.status==='Đã nộp'?'#1ba77f':a.status==='Đã chấm'?'#c08430':'#596df5'}">▣</div><div class="tasktext"><strong>${esc(a.title)}</strong><small>${esc(courseById(a.courseId).name)} · Hạn ${fmtDate(a.due)}</small></div>${role==='teacher'?`<button class="btn soft" onclick="event.stopPropagation();openGrade(${a.id})">Chấm bài</button>`:statusTag(a.status)}</div>`).join('')||'<div class="empty">Chưa có bài tập nào.</div>'}
function dashboard(){let c=courseList();let todayLabel=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());if(role==='student')return `
<div class="welcome"><div><div class="eyebrow">${todayLabel}</div><h1>Xin chào, <span class="hello">${esc(sessionUser.name.split(/\s+/).slice(-2).join(' ' ))}</span></h1><p>Sẵn sàng tiếp tục hành trình học tập của bạn chưa?<br>Đây là không gian học tập cá nhân của bạn hôm nay.</p></div><div class="actions"><button class="btn" onclick="showToast('Đã tải dữ liệu demo mới nhất.')">↻ Làm mới</button><button class="btn primary" onclick="page='courses';render()">＋ Khám phá khóa học</button></div></div>
<div class="stats">${statCard('Khóa học của tôi',String(c.length),'▤','#eef0ff','#5b6cf4','Khóa học trong dữ liệu demo')}${statCard('Bài tập cần hoàn thành',String(db.assignments.filter(a=>a.status==='Chưa nộp'||a.status==='Quá hạn').length),'▣','#fff2df','#9b5c0b','Chưa nộp hoặc đã quá hạn')}${statCard('Điểm trung bình',(db.grades.filter(g=>g.userId===Number(sessionUser?.id)).length?db.grades.filter(g=>g.userId===Number(sessionUser?.id)).reduce((sum,g)=>sum+g.score,0)/db.grades.filter(g=>g.userId===Number(sessionUser?.id)).length:0).toFixed(1),'★','#e4f8f0','#157b5c','Trên thang điểm 10')}${statCard('Tiến độ học tập',(c.length?Math.round(c.reduce((sum,x)=>sum+Number(x.progress||0),0)/c.length):0)+'%','◷','#f2eafd','#7651b5','Trung bình tiến độ các khóa học')}</div>
<div class="layout2"><div class="panel"><div class="panelhead"><div><h2>Tiếp tục học tập</h2><p>Các khóa học bạn đang theo học</p></div><button class="textlink" onclick="page='courses';render()">Xem tất cả →</button></div><div class="coursegrid">${c.slice(0,4).map(courseCard).join('')}</div></div><div class="panel"><div class="panelhead"><div><h2>Lịch học sắp tới</h2><p>Đừng bỏ lỡ buổi học tiếp theo</p></div><button class="textlink" onclick="showToast('Lịch đầy đủ sẽ được bổ sung ở phiên bản tiếp theo.')">Lịch →</button></div><div class="schedulelist"><div class="scheduleitem"><div class="datechip"><strong>12</strong><span>Th 2</span></div><div><h3>Cơ sở dữ liệu nâng cao</h3><p>Phụ thuộc hàm và chuẩn hóa dữ liệu</p><div class="tiny">◷ 07:30 – 09:45 · Phòng A-08.05</div></div></div><div class="divider"></div><div class="scheduleitem"><div class="datechip" style="background:#e4f8f0;color:#18a17b"><strong>14</strong><span>Th 4</span></div><div><h3>Lập trình ứng dụng Web</h3><p>Thực hành Form và xử lý dữ liệu</p><div class="tiny">◷ 09:50 – 12:00 · Trực tuyến</div></div></div><div class="divider"></div><div class="scheduleitem"><div class="datechip" style="background:#fff2df;color:#c28531"><strong>16</strong><span>Th 6</span></div><div><h3>An toàn ứng dụng</h3><p>Kiểm soát truy cập và phân quyền</p><div class="tiny">◷ 13:00 – 15:15 · Phòng B-04.02</div></div></div></div></div></div>
<div class="panel" style="margin-top:20px"><div class="panelhead"><div><h2>Bài tập gần hạn</h2><p>Quản lý deadline để không bị dí vào phút cuối</p></div><button class="textlink" onclick="page='assignments';render()">Xem tất cả →</button></div><div class="tasklist">${assignmentCards(4)}</div></div><div class="footerhint">E-Learn Demo · Dữ liệu minh họa phục vụ đồ án Cơ sở dữ liệu nâng cao</div>`;
if(role==='teacher')return `<div class="welcome"><div><div class="eyebrow">KHÔNG GIAN GIẢNG DẠY</div><h1>Chào giảng viên, <span class="hello">${esc(sessionUser.name)}</span></h1><p>Quản lý lớp học, nội dung và tiến độ của sinh viên tại một nơi.</p></div><div class="actions"><button class="btn" onclick="showToast('Bảng điều khiển đã được cập nhật.')">↻ Làm mới</button><button class="btn primary" onclick="openCreateAssignment()">＋ Giao bài tập</button></div></div><div class="stats">${statCard('Lớp học phần',String(c.length),'▤','#eef0ff','#5b6cf4','Đang phụ trách')}${statCard('Sinh viên',String(c.reduce((sum,x)=>sum+Number(x.students||0),0)),'♙','#e4f8f0','#157b5c','Tổng sĩ số các lớp')}${statCard('Bài cần chấm',String(db.assignments.filter(a=>c.some(x=>x.id===a.courseId)).reduce((s,a)=>s+a.submissions.filter(x=>x.score==null).length,0)),'▣','#fff2df','#d28a2d','Chưa có điểm')}${statCard('Tỷ lệ hoàn thành',(c.length?Math.round(c.reduce((sum,x)=>sum+Number(x.progress||0),0)/c.length):0)+'%','◷','#f2eafd','#7651b5','Trung bình tiến độ các lớp')}</div><div class="layout2"><div class="panel"><div class="panelhead"><div><h2>Lớp học đang phụ trách</h2><p>Theo dõi nội dung và tiến độ giảng dạy</p></div><button class="textlink" onclick="page='courses';render()">Quản lý lớp →</button></div><div class="coursegrid">${c.map(courseCard).join('')}</div></div><div class="panel"><div class="panelhead"><div><h2>Việc cần xử lý</h2><p>Bài nộp chờ chấm điểm</p></div><button class="textlink" onclick="page='assignments';render()">Tất cả →</button></div><div class="tasklist">${assignmentCards(5)}</div></div></div><div class="footerhint">E-Learn Demo · Vai trò Giảng viên</div>`;
return `<div class="welcome"><div><div class="eyebrow">QUẢN TRỊ HỆ THỐNG</div><h1>Tổng quan <span class="hello">E-Learn</span></h1><p>Theo dõi dữ liệu nền tảng và quản lý các đối tượng trong hệ thống.</p></div><div class="actions"><button class="btn" onclick="showToast('Dữ liệu đã được đồng bộ trong trình duyệt.')">↻ Làm mới</button><button class="btn primary" onclick="openAddUser()">＋ Tạo tài khoản</button></div></div><div class="stats">${statCard('Tổng người dùng',String(db.users.length),'♙','#eef0ff','#5b6cf4','Tài khoản demo')}${statCard('Sinh viên',String(db.users.filter(u=>u.role==='student').length),'♧','#e4f8f0','#1baa7f','Đang hoạt động')}${statCard('Khóa học',String(db.courses.length),'▤','#fff2df','#d28a2d','Danh mục và lớp học')}${statCard('Bài tập',String(db.assignments.length),'▣','#f2eafd','#9c6be5','Trong hệ thống demo')}</div><div class="layout2"><div class="panel"><div class="panelhead"><div><h2>Tổng quan dữ liệu</h2><p>Phân bố đối tượng được lưu trong demo</p></div><button class="textlink" onclick="page='reports';render()">Chi tiết →</button></div><div class="chartbars">${[['Sinh viên',db.users.filter(u=>u.role==='student').length,100],['Giảng viên',db.users.filter(u=>u.role==='teacher').length,55],['Quản trị',db.users.filter(u=>u.role==='admin').length,35],['Khóa học',db.courses.length,70],['Bài tập',db.assignments.length,82]].map(x=>`<div class="chartbar"><span style="height:${Math.max(8,x[2])}%"></span><small>${x[0]}</small></div>`).join('')}</div><div class="chartlegend"><span><i></i> Số lượng đối tượng demo</span><span>Dữ liệu minh họa, không phải thống kê thực tế</span></div></div><div class="panel"><div class="panelhead"><div><h2>Hoạt động gần đây</h2><p>Các số liệu để kiểm thử giao diện</p></div></div><div class="schedulelist"><div class="scheduleitem"><div class="taskicon" style="background:#e4f8f0;color:#1baa7f">♙</div><div><h3>Quản lý tài khoản</h3><p>${db.users.length} tài khoản trong dữ liệu demo</p><div class="tiny">Dữ liệu cục bộ</div></div></div><div class="divider"></div><div class="scheduleitem"><div class="taskicon" style="background:#eef0ff;color:#596df5">▤</div><div><h3>Danh mục khóa học</h3><p>${db.courses.length} khóa học/lớp mẫu</p><div class="tiny">Có thể thêm khóa học</div></div></div><div class="divider"></div><div class="scheduleitem"><div class="taskicon" style="background:#fff2df;color:#c28531">▣</div><div><h3>Quản lý bài tập</h3><p>${db.assignments.length} bài tập và bài kiểm tra mẫu</p><div class="tiny">Có thể thêm bài tập</div></div></div></div></div></div><div class="footerhint">E-Learn Demo · Vai trò Quản trị viên</div>`}
function pageHeader(title,sub,btnText='',btnAction=''){return `<div class="pagehead"><div><div class="eyebrow">E-LEARN / ${title.toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div>${btnText?`<button class="btn primary" onclick="${btnAction}">＋ ${btnText}</button>`:''}</div>`}
function coursesPage(){let list=courseList();return `${pageHeader(role==='teacher'?'Lớp học của tôi':'Khám phá khóa học',role==='teacher'?'Quản lý nội dung các lớp học phần đang phụ trách.':'Tìm kiếm và truy cập các khóa học trong hệ thống.',role==='teacher'?'Thêm khóa học':role==='admin'?'Thêm khóa học':'',role==='teacher'||role==='admin'?'openAddCourse()':'')}<div class="toolbar"><input class="filterinput" id="courseSearch" type="search" aria-label="Tìm theo tên hoặc mã khóa học" placeholder="Tìm theo tên hoặc mã khóa học..." oninput="filterCourses()"><select class="filterselect" id="courseCategory" onchange="filterCourses()"><option value="">Tất cả danh mục</option><option>Cơ sở dữ liệu</option><option>Phát triển phần mềm</option><option>An toàn thông tin</option><option>Phân tích thiết kế</option></select></div><div class="coursegrid" id="courseGrid">${list.map(courseCard).join('')}</div><div class="footerhint">Nhấn vào một khóa học để xem nội dung, bài tập và thông tin lớp.</div>`}
function filterCourses(){let q=(document.getElementById('courseSearch')?.value||'').toLowerCase(),cat=document.getElementById('courseCategory')?.value||'';let list=courseList().filter(c=>(c.name+' '+c.code+' '+c.teacher).toLowerCase().includes(q)&&(!cat||c.category===cat));document.getElementById('courseGrid').innerHTML=list.map(courseCard).join('')||'<div class="empty">Không tìm thấy khóa học phù hợp.</div>'}
function openCourse(id){
 let c=courseById(id),assignments=db.assignments.filter(a=>a.courseId===id);
 let enrolled=(db.enrollments||[]).some(e=>Number(e.courseId)===Number(id)&&Number(e.studentId)===Number(sessionUser?.id));
 let body=`<div class="coursecover ${c.color||'cover1'}" style="height:120px;border-radius:12px;margin-bottom:17px"><span class="tag">${esc(c.code)}</span><span class="symbol">${esc(c.symbol||'DB')}</span></div><p style="color:#59657c;font-size:13px;line-height:1.7">${esc(c.description||'Chưa có mô tả.')}</p><div class="tabrow"><button class="tab active" onclick="switchCourseTab('lessons',${id})">Bài học (${c.lessons.length})</button><button class="tab" onclick="switchCourseTab('tasks',${id})">Bài tập (${assignments.length})</button><button class="tab" onclick="switchCourseTab('info',${id})">Thông tin</button></div><div id="courseTabContent">${lessonRows(c)}</div>`;
 let footer=`<button class="btn" onclick="closeModal()">Đóng</button>`;
 if(role==='student')footer+=enrolled?`<button class="btn soft" disabled aria-disabled="true">✓ Đã đăng ký lớp</button>`:`<button class="btn primary" onclick="enrollCourse(${id})">＋ Đăng ký học phần</button>`;
 if(role==='teacher'||role==='admin')footer+=`<button class="btn primary" onclick="closeModal();openAddLesson(${id})">＋ Thêm bài học</button>`;
 showModal(c.name,`${c.teacher} · ${c.term}`,body,footer)
}
function enrollCourse(courseId){
 if(role!=='student'){showToast('Chỉ sinh viên mới có thể đăng ký học phần.');return}
 db.enrollments=db.enrollments||[];
 if(db.enrollments.some(e=>Number(e.courseId)===Number(courseId)&&Number(e.studentId)===Number(sessionUser?.id))){showToast('Bạn đã đăng ký lớp học phần này.');return}
 db.enrollments.push({courseId:Number(courseId),studentId:Number(sessionUser.id),progress:0});
 let c=courseById(courseId);c.students=(c.students||0)+1;c.progress=0;
 save();closeModal();render();showToast('Đăng ký học phần thành công.');
}
function lessonRows(c){return c.lessons.map((l,i)=>`<div class="lessonrow"><div class="lessonnum">${String(i+1).padStart(2,'0')}</div><div><strong>${esc(l.title)}</strong><small>${esc(l.type)} · ${esc(l.duration)}</small></div><button class="btn" onclick="showToast('Đã mở bài học demo: ${esc(l.title).replace(/'/g,'')}')">Xem ↗</button></div>`).join('')||'<div class="empty">Chưa có bài học.</div>'}
function switchCourseTab(tab,id){let c=courseById(id),el=document.getElementById('courseTabContent');document.querySelectorAll('.tab').forEach((x,i)=>x.classList.toggle('active',['lessons','tasks','info'][i]===tab));if(tab==='lessons')el.innerHTML=lessonRows(c);if(tab==='tasks')el.innerHTML=db.assignments.filter(a=>a.courseId===id).map(a=>`<div class="task"><div class="tasktext"><strong>${esc(a.title)}</strong><small>Hạn ${fmtDate(a.due)} · ${a.points} điểm</small></div>${statusTag(a.status)}<button class="btn" onclick="openAssignment(${a.id})">Chi tiết</button></div>`).join('')||'<div class="empty">Chưa có bài tập trong khóa học.</div>';if(tab==='info')el.innerHTML=`<div class="notice"><strong>Mã khóa học:</strong> ${esc(c.code)}<br><strong>Giảng viên:</strong> ${esc(c.teacher)}<br><strong>Học kỳ:</strong> ${esc(c.term)}<br><strong>Sĩ số hiện tại:</strong> ${c.students} sinh viên<br><strong>Tiến độ:</strong> ${c.progress}%</div><p style="font-size:12px;color:#69738d;line-height:1.7">${esc(c.description)}</p>`}
function assignmentsPage(){let list=tasksForUser();return `${pageHeader(role==='teacher'?'Quản lý bài tập':'Bài tập & kiểm tra',role==='teacher'?'Tạo bài tập và theo dõi bài nộp của sinh viên.':'Theo dõi hạn nộp, trạng thái bài tập và kết quả học tập.',role==='teacher'?'Giao bài tập':'',role==='teacher'?'openCreateAssignment()':'')}<div class="toolbar"><input class="filterinput" id="taskSearch" type="search" aria-label="Tìm bài tập" placeholder="Tìm bài tập..." oninput="filterTasks()"><select class="filterselect" id="taskStatus" aria-label="Lọc bài tập theo trạng thái" onchange="filterTasks()"><option value="">Tất cả trạng thái</option><option>Chưa nộp</option><option>Đã nộp</option><option>Đã chấm</option><option>Chưa mở</option></select><select class="filterselect" id="taskCourse" aria-label="Lọc bài tập theo khóa học" onchange="filterTasks()"><option value="">Tất cả khóa học</option>${courseList().map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>Bài tập</th><th>Khóa học</th><th>Hạn nộp</th><th>Điểm tối đa</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="taskRows">${taskRows(list)}</tbody></table></div></div><div class="footerhint">Bài nộp được lưu trong MySQL sau khi máy chủ xác nhận quyền và dữ liệu hợp lệ.</div>`}
function taskRows(list){return list.map(a=>`<tr><td><div class="person"><div class="taskicon" style="background:#eef0ff;color:#596df5;width:32px;height:32px;font-size:13px">▣</div><div><span class="strong">${esc(a.title)}</span><small>${esc(a.type)}</small></div></div></td><td>${esc(courseById(a.courseId).name)}</td><td>${fmtDate(a.due)}</td><td>${a.points}</td><td>${statusTag(a.status)}</td><td><button class="btn ${role==='teacher'?'soft':''}" onclick="${role==='teacher'?`openGrade(${a.id})`:`openAssignment(${a.id})`}">${role==='teacher'?'Xem bài nộp':'Chi tiết'}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Không có bài tập phù hợp.</div></td></tr>'}
function filterTasks(){let q=(document.getElementById('taskSearch')?.value||'').toLowerCase(),s=document.getElementById('taskStatus')?.value||'',c=document.getElementById('taskCourse')?.value||'';let list=tasksForUser().filter(a=>(a.title+' '+courseById(a.courseId).name).toLowerCase().includes(q)&&(!s||a.status===s)&&(!c||a.courseId===+c));document.getElementById('taskRows').innerHTML=taskRows(list);applyTableLabels(document.getElementById('taskRows').closest('table'))}
function openAssignment(id){let a=db.assignments.find(x=>x.id===id),c=courseById(a.courseId),sub=a.submissions.find(s=>s.userId===Number(sessionUser?.id));showModal(a.title,c.name,`<div class="notice"><strong>Hạn nộp:</strong> ${fmtDate(a.due)}<br><strong>Điểm tối đa:</strong> ${a.points}<br><strong>Trạng thái:</strong> ${a.status}</div><p style="font-size:12px;line-height:1.75;color:#626d89">${esc(a.description)}</p>${sub?`<div class="field"><label>Bài đã nộp</label><textarea readonly>${esc(sub.answer)}</textarea></div>${sub.score!=null?`<div class="notice"><strong>Điểm:</strong> ${sub.score}/${a.points}<br><strong>Nhận xét:</strong> ${esc(sub.feedback||'Chưa có nhận xét')}</div>`:'<p style="font-size:11px;color:#7c86a1">Bài đã nộp, đang chờ giảng viên chấm.</p>'}`:''}`,`<button class="btn" onclick="closeModal()">Đóng</button>${role==='student'&&a.status!=='Đã chấm'&&a.status!=='Chưa mở'?`<button class="btn primary" onclick="openSubmit(${id})">${sub?'Cập nhật bài nộp':'Nộp bài'}</button>`:''}`)}
function openSubmit(id){let a=db.assignments.find(x=>x.id===id),old=a.submissions.find(s=>s.userId===Number(sessionUser?.id));showModal(old?'Cập nhật bài nộp':'Nộp bài tập',a.title,`<div class="notice">Demo hiện lưu nội dung câu trả lời hoặc đường dẫn tệp. Upload tệp thật sẽ được bổ sung khi có backend.</div><form id="submitForm"><div class="field"><label>Nội dung bài nộp / đường dẫn tệp</label><textarea name="answer" placeholder="Nhập nội dung hoặc dán đường dẫn Google Drive..." required>${esc(old?.answer||'')}</textarea></div></form>`,`<button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="submitWork(${id})">Gửi bài nộp</button>`)}
function submitWork(id){let form=document.getElementById('submitForm');if(!form.reportValidity())return;let answer=new FormData(form).get('answer');let a=db.assignments.find(x=>x.id===id),s=a.submissions.find(x=>x.userId===Number(sessionUser?.id));if(s){s.answer=answer;s.submitted=new Date().toISOString().slice(0,10);s.score=null;s.feedback='';db.grades=db.grades.filter(g=>!(Number(g.userId)===Number(s.userId)&&Number(g.courseId)===Number(a.courseId)&&(Number(g.assignmentId)===Number(id)||g.work===a.title)))}else a.submissions.push({userId:Number(sessionUser.id),submitted:new Date().toISOString().slice(0,10),answer,score:null,feedback:''});a.status='Đã nộp';save();closeModal();render();showToast('Đã lưu bài nộp demo thành công.')}
function openCreateAssignment(){let opts=courseList().map(c=>({value:c.id,label:c.name}));showModal('Giao bài tập mới','Tạo bài tập cho lớp học phần',`<form id="createTaskForm" class="formgrid">${field('Tên bài tập','title','Ví dụ: Bài tập chương 2','text','',true)}${selectField('Khóa học','courseId',opts,true)}${selectField('Loại bài tập','type',[{value:'Bài tập cá nhân',label:'Bài tập cá nhân'},{value:'Bài tập nhóm',label:'Bài tập nhóm'},{value:'Trắc nghiệm',label:'Trắc nghiệm'}])}${field('Hạn nộp','due','', 'date','2026-10-25')}${field('Điểm tối đa','points','10','number','10')}${areaField('Mô tả yêu cầu','description','Mô tả yêu cầu bài tập...',true)}</form>`,`<button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="createAssignment()">Tạo bài tập</button>`)}
function createAssignment(){let f=document.getElementById('createTaskForm');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));let c=courseById(+d.courseId);db.assignments.push({id:nextRecordId(db.assignments),courseId:+d.courseId,title:d.title,type:d.type,due:d.due,points:+d.points,status:'Chưa nộp',submissions:[],description:d.description});save();closeModal();page='assignments';render();showToast('Đã tạo bài tập và lưu vào dữ liệu demo.')}
function openGrade(id){let a=db.assignments.find(x=>x.id===id);let subs=a.submissions;if(!subs.length){showModal('Danh sách bài nộp',a.title,'<div class="empty">Chưa có sinh viên nộp bài. Hãy chuyển sang vai trò Sinh viên và nộp thử bài tập để kiểm tra luồng.</div>','<button class="btn" onclick="closeModal()">Đóng</button>');return}let content=subs.map((s,i)=>`<div class="panel" style="box-shadow:none;margin-bottom:12px;padding:15px"><div class="person"><div class="avatar">${initials(userById(s.userId).name)}</div><div style="flex:1"><strong style="font-size:12px">${esc(userById(s.userId).name)}</strong><small style="display:block;color:#7b85a0;margin-top:3px">Nộp ngày ${fmtDate(s.submitted)}</small></div>${s.score==null?'<span class="pill orange">Chờ chấm</span>':`<span class="pill green">${s.score}/${a.points} điểm</span>`}</div><div class="field" style="margin-top:13px"><label>Nội dung bài nộp</label><textarea readonly>${esc(s.answer)}</textarea></div><div class="formgrid"><div class="field"><label>Điểm (tối đa ${a.points})</label><input id="score_${i}" type="number" min="0" max="${a.points}" step="0.25" value="${s.score??''}" placeholder="Nhập điểm"></div><div class="field"><label>Nhận xét</label><input id="feedback_${i}" value="${esc(s.feedback||'')}" placeholder="Nhận xét ngắn"></div></div><button class="btn primary" onclick="gradeSubmission(${id},${i})">Lưu điểm</button></div>`).join('');showModal('Chấm bài sinh viên',a.title,content,'<button class="btn" onclick="closeModal()">Đóng</button>')}
function gradeSubmission(id,index){let a=db.assignments.find(x=>x.id===id),s=a.submissions[index],input=document.getElementById('score_'+index),score=input?.value,feedback=document.getElementById('feedback_'+index)?.value.trim()||'';if(score===''||!Number.isFinite(Number(score))||Number(score)<0||Number(score)>a.points){showToast(`Điểm phải nằm trong khoảng 0–${a.points}.`);input?.focus();return}let numericScore=Number(score),existing=db.grades.find(g=>g.userId===s.userId&&g.courseId===a.courseId&&g.work===a.title);if(existing){existing.score=numericScore;existing.max=a.points;existing.feedback=feedback}else{db.grades.push({userId:s.userId,courseId:a.courseId,work:a.title,score:numericScore,max:a.points,feedback})}s.score=numericScore;s.feedback=feedback;if(s.userId===Number(sessionUser?.id))a.status='Đã chấm';save();closeModal();render();showToast('Đã lưu điểm và nhận xét.')}
function openAddUser(){showModal('Tạo tài khoản','Thêm một người dùng vào dữ liệu demo',`<form id="addUserForm" class="formgrid">${field('Họ và tên','name','Nhập họ tên','text','',true)}${field('Mã người dùng / MSSV','code','Ví dụ: 2380600000')}${field('Email','email','name@example.com','email')}${selectField('Vai trò','role',[{value:'student',label:'Sinh viên'},{value:'teacher',label:'Giảng viên'},{value:'admin',label:'Quản trị viên'}])}</form>`,`<button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="createUser()">Tạo tài khoản</button>`)}
function createUser(){let f=document.getElementById('addUserForm');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));d.name=d.name.trim();d.code=d.code.trim();d.email=d.email.trim().toLowerCase();if(db.users.some(u=>u.code.trim().toLowerCase()===d.code.toLowerCase()||u.email.trim().toLowerCase()===d.email)){showToast('Mã người dùng hoặc email đã tồn tại.');return}db.users.push({id:Math.max(0,...db.users.map(u=>u.id))+1,...d,status:'Hoạt động'});save();closeModal();render();showToast('Đã tạo tài khoản demo. Mật khẩu mặc định: Demo123!.')}
function openAddCourse(){if(role==='teacher'){showModal('Thêm lớp học phần','Lớp mới sẽ được phân công cho tài khoản giảng viên hiện tại',`<form id="addCourseForm" class="formgrid">${field('Tên khóa học','name','Tên khóa học','text','',true)}${field('Mã khóa học','code','VD: CSDL-02')}${selectField('Danh mục','category',[{value:'Cơ sở dữ liệu',label:'Cơ sở dữ liệu'},{value:'Phát triển phần mềm',label:'Phát triển phần mềm'},{value:'An toàn thông tin',label:'An toàn thông tin'},{value:'Phân tích thiết kế',label:'Phân tích thiết kế'}])}${field('Học kỳ','term','Học kỳ 1 · 2026–2027','text','Học kỳ 1 · 2026–2027',true)}${areaField('Mô tả','description','Mục tiêu và nội dung khóa học...',true)}</form>`,`<button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="createCourse()">Lưu lớp học phần</button>`);return}if(!db.users.some(u=>u.role==='teacher')){showModal('Chưa có giảng viên','Hãy tạo tài khoản giảng viên trước khi mở khóa học.','<div class="empty">Danh sách giảng viên hiện đang trống.</div>','<button class="btn" onclick="closeModal()">Đóng</button><button class="btn primary" onclick="closeModal();openAddUser()">Tạo tài khoản</button>');return}showModal('Thêm khóa học','Tạo một khóa học mẫu mới',`<form id="addCourseForm" class="formgrid">${field('Tên khóa học','name','Tên khóa học','text','',true)}${field('Mã khóa học','code','VD: CSDL-02')}${selectField('Giảng viên phụ trách','teacher',db.users.filter(u=>u.role==='teacher').map(u=>({value:u.name,label:u.name})),true)}${selectField('Danh mục','category',[{value:'Cơ sở dữ liệu',label:'Cơ sở dữ liệu'},{value:'Phát triển phần mềm',label:'Phát triển phần mềm'},{value:'An toàn thông tin',label:'An toàn thông tin'},{value:'Phân tích thiết kế',label:'Phân tích thiết kế'}])}${field('Học kỳ','term','Học kỳ 1 · 2026–2027','text','Học kỳ 1 · 2026–2027',true)}${areaField('Mô tả','description','Mục tiêu và nội dung khóa học...',true)}</form>`,`<button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="createCourse()">Lưu khóa học</button>`)}
function createCourse(){let f=document.getElementById('addCourseForm');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));if(db.courses.some(c=>c.code.toLowerCase()===d.code.toLowerCase())){showToast('Mã khóa học đã tồn tại.');return}let t=role==='teacher'?sessionUser:db.users.find(u=>u.name===d.teacher&&u.role==='teacher');if(!t){showToast('Vui lòng chọn giảng viên hợp lệ.');return}let courseData={id:nextRecordId(db.courses),name:d.name,code:d.code,term:d.term||'Học kỳ 1 · 2026–2027',teacher:t.name,teacherId:t.id,category:d.category||'Khác',description:d.description||'',students:0,progress:0,color:['cover1','cover2','cover3','cover4'][db.courses.length%4],symbol:'DB',lessons:[]};db.courses.push(courseData);save();closeModal();page='courses';render();showToast('Đã tạo khóa học demo.')}
function openAddLesson(id){let c=courseById(id);showModal('Thêm bài học',c.name,`<form id="addLessonForm" class="formgrid">${field('Tên bài học','title','Tên bài học','text','',true)}${selectField('Loại nội dung','type',[{value:'Video bài giảng',label:'Video bài giảng'},{value:'Tài liệu PDF',label:'Tài liệu PDF'},{value:'Thực hành',label:'Thực hành'},{value:'Tài liệu + video',label:'Tài liệu + video'}])}${field('Thời lượng','duration','Ví dụ: 20 phút','text','20 phút',true)}</form>`,`<button class="btn" onclick="closeModal()">Hủy</button><button class="btn primary" onclick="createLesson(${id})">Thêm bài học</button>`)}
function createLesson(id){let f=document.getElementById('addLessonForm');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f)),c=courseById(id);c.lessons.push({id:nextRecordId(db.courses.flatMap(c=>c.lessons)),...d});save();closeModal();render();showToast('Đã thêm bài học.')}
function usersPage(){let users=db.users;return `${pageHeader('Quản lý người dùng','Quản lý tài khoản, mã định danh và vai trò truy cập.','Tạo tài khoản','openAddUser()')}<div class="toolbar"><input class="filterinput" id="userSearch" type="search" aria-label="Tìm theo tên, mã số hoặc email" placeholder="Tìm tên, mã số hoặc email..." oninput="filterUsers()"><select class="filterselect" id="userRole" aria-label="Lọc người dùng theo vai trò" onchange="filterUsers()"><option value="">Tất cả vai trò</option><option value="student">Sinh viên</option><option value="teacher">Giảng viên</option><option value="admin">Quản trị viên</option></select></div><div class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>Người dùng</th><th>Mã định danh</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th></tr></thead><tbody id="userRows">${userRows(users)}</tbody></table></div></div><div class="footerhint">Thông tin trong danh sách là dữ liệu mẫu, không đại diện danh sách người dùng thực của trường.</div>`}
function userRows(users){return users.map(u=>`<tr><td><div class="person"><div class="avatar">${initials(u.name)}</div><div><span class="strong">${esc(u.name)}</span><small>Tài khoản #${u.id}</small></div></div></td><td>${esc(u.code)}</td><td>${esc(u.email)}</td><td>${roleTag(u.role)}</td><td><span class="pill green">${esc(u.status)}</span></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Không tìm thấy tài khoản.</div></td></tr>'}
function filterUsers(){let q=(document.getElementById('userSearch')?.value||'').toLowerCase(),r=document.getElementById('userRole')?.value||'';document.getElementById('userRows').innerHTML=userRows(db.users.filter(u=>(u.name+' '+u.code+' '+u.email).toLowerCase().includes(q)&&(!r||u.role===r)));applyTableLabels(document.getElementById('userRows').closest('table'))}
function gradesPage(){let rows=role==='teacher'?db.grades.filter(g=>courseList().some(c=>c.id===g.courseId)):db.grades.filter(g=>g.userId===Number(sessionUser?.id));return `${pageHeader('Bảng điểm','Theo dõi kết quả học tập và nhận xét của giảng viên.')}<div class="stats">${statCard('Số đầu điểm',String(rows.length),'▥','#eef0ff','#5b6cf4','Các kết quả trong dữ liệu demo')}${statCard('Điểm trung bình',rows.length?(rows.reduce((s,g)=>s+g.score,0)/rows.length).toFixed(1):'—','★','#e4f8f0','#1baa7f','Thang điểm 10')}${statCard('Đầu điểm cao nhất',rows.length?Math.max(...rows.map(g=>g.score)).toFixed(1):'—','↗','#fff2df','#d28a2d','Điểm đã ghi nhận')}${statCard('Phản hồi',String(rows.filter(g=>g.feedback).length),'✎','#f2eafd','#9c6be5','Có nhận xét của giảng viên')}</div><div class="panel"><div class="panelhead"><div><h2>${role==='teacher'?'Kết quả trong các lớp phụ trách':'Kết quả của tôi'}</h2><p>Điểm số được lưu theo đầu điểm và khóa học</p></div></div><div class="tablewrap"><table class="table"><thead><tr><th>${role==='teacher'?'Sinh viên':'Đầu điểm'}</th><th>Khóa học</th>${role==='teacher'?'<th>Đầu điểm</th>':'<th>Điểm</th>'}<th>Nhận xét</th></tr></thead><tbody>${rows.map(g=>`<tr><td>${role==='teacher'?esc(userById(g.userId).name):`<span class="strong">${esc(g.work)}</span>`}</td><td>${esc(courseById(g.courseId).name)}</td><td><span class="strong">${role==='teacher'?esc(g.work):g.score+' / '+g.max}</span>${role==='teacher'?`<small style="display:block;color:#7e88a0;margin-top:4px">${g.score}/${g.max} điểm</small>`:''}</td><td style="white-space:normal;min-width:160px">${esc(g.feedback||'Chưa có nhận xét')}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">Chưa có dữ liệu điểm.</div></td></tr>'}</tbody></table></div></div>`}
function reportsPage(){let summaryRows=db.courses.map(c=>`<tr><td class="strong">${esc(c.name)}</td><td>${c.students}</td><td>${db.assignments.filter(a=>a.courseId===c.id).length}</td><td>${c.lessons.length}</td><td>${c.progress||0}%</td></tr>`).join('');let submissionRows=db.assignments.map(a=>{let graded=a.submissions.filter(s=>s.score!=null).length;return `<tr><td class="strong">${esc(a.title)}</td><td>${esc(courseById(a.courseId).name)}</td><td>${a.submissions.length}</td><td>${graded}</td><td>${a.submissions.length-graded}</td></tr>`}).join('');return `${pageHeader('Báo cáo dữ liệu','Các báo cáo tổng hợp truy vấn từ cơ sở dữ liệu quan hệ.')}<div class="notice"><strong>Nguồn dữ liệu:</strong> ${backendConnected?'MySQL backend · Các bảng tổng hợp được lấy từ SQL VIEW v_course_summary và v_submission_summary.':'Dữ liệu mẫu ở chế độ trình duyệt. Chạy server.py để xem báo cáo từ SQL VIEW.'}</div><div class="layout2"><div class="panel"><div class="panelhead"><div><h2>Thống kê theo khóa học</h2><p>Sĩ số, số bài tập, số bài học và tiến độ trung bình</p></div><span class="pill blue">SQL VIEW</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Khóa học</th><th>HV</th><th>Bài tập</th><th>Bài học</th><th>Tiến độ</th></tr></thead><tbody id="sqlCourseSummaryRows">${summaryRows||'<tr><td colspan="5">Chưa có dữ liệu.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panelhead"><div><h2>Thống kê bài nộp</h2><p>Số lượng đã nộp, đã chấm và đang chờ chấm</p></div><span class="pill blue">SQL VIEW</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Bài tập</th><th>Khóa học</th><th>Nộp</th><th>Đã chấm</th><th>Chờ chấm</th></tr></thead><tbody id="sqlSubmissionSummaryRows">${submissionRows||'<tr><td colspan="5">Chưa có dữ liệu.</td></tr>'}</tbody></table></div></div></div><div class="footerhint">Dữ liệu mẫu chỉ nhằm minh họa nghiệp vụ; không phải số liệu thực tế của trường.</div>`}
async function loadSqlReports(){if(!backendConnected)return;try{const [cr,sr]=await Promise.all([fetch('/api/reports/course-summary'),fetch('/api/reports/submission-summary')]);if(!cr.ok||!sr.ok)throw new Error('Report API unavailable');const cd=await cr.json(),sd=await sr.json();const courseBody=document.getElementById('sqlCourseSummaryRows'),submissionBody=document.getElementById('sqlSubmissionSummaryRows');if(courseBody)courseBody.innerHTML=cd.items.map(c=>`<tr><td class="strong">${esc(c.course_name)}</td><td>${c.student_count}</td><td>${c.assignment_count}</td><td>${c.lesson_count}</td><td>${Number(c.avg_progress).toLocaleString('vi-VN')}%</td></tr>`).join('')||'<tr><td colspan="5">Chưa có dữ liệu.</td></tr>';if(submissionBody)submissionBody.innerHTML=sd.items.map(a=>`<tr><td class="strong">${esc(a.title)}</td><td>${esc(a.course_name)}</td><td>${a.submission_count}</td><td>${a.graded_count}</td><td>${a.pending_count}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có dữ liệu.</td></tr>';applyTableLabels(document.getElementById('content'))}catch(e){showToast('Không tải được báo cáo SQL; đang hiển thị dữ liệu dự phòng.')}}
function showHelp(){let persistence=backendConnected?'Dữ liệu được lưu trong MySQL. Đăng nhập và quyền thao tác được kiểm tra ở backend.':'Backend chưa kết nối; hãy chạy start_windows.bat rồi mở địa chỉ localhost.';let resetButton=role==='admin'?'<button class="btn danger" onclick="resetDemo()">Đặt lại dữ liệu demo</button>':'';showModal('Hướng dẫn dùng demo','Thử luồng học tập qua ba tài khoản đã xác thực',`<div class="notice"><strong>1. Sinh viên:</strong> đăng ký học phần, mở Bài tập & kiểm tra và nộp bài.<br><br><strong>2. Giảng viên:</strong> đổi tài khoản → Quản lý bài tập → xem bài nộp → nhập điểm và nhận xét.<br><br><strong>3. Quản trị viên:</strong> đổi tài khoản → Quản lý người dùng hoặc Báo cáo dữ liệu.<br><br><strong>Lưu dữ liệu:</strong> ${persistence}</div><p style="font-size:12px;color:#59657c;line-height:1.6">Đặt lại dữ liệu demo sẽ khôi phục bộ dữ liệu ban đầu trên máy chủ; thao tác này không thể hoàn tác.</p>`,`${resetButton}<button class="btn primary" onclick="closeModal()">Đã hiểu</button>`)}
async function resetDemo(){if(role!=='admin'){showToast('Chỉ quản trị viên được đặt lại dữ liệu.');return}if(!confirm('Đặt lại toàn bộ dữ liệu demo trên máy chủ? Thao tác không thể hoàn tác.'))return;try{const r=await fetch('/api/reset',{method:'POST',credentials:'same-origin'}),result=await r.json();if(!r.ok)throw new Error(result.error||'Không thể đặt lại dữ liệu');db=result.state;closeModal();render();showToast('Đã khôi phục dữ liệu demo ban đầu.')}catch(e){showToast(e.message||'Không thể đặt lại dữ liệu.')}}
function globalFind(){let q=document.getElementById('globalSearch').value.trim().toLowerCase();if(!q){return}let c=db.courses.find(c=>(c.name+' '+c.code).toLowerCase().includes(q));let a=db.assignments.find(a=>a.title.toLowerCase().includes(q));if(c){page='courses';render();setTimeout(()=>openCourse(c.id),30)}else if(a){page='assignments';render();setTimeout(()=>openAssignment(a.id),30)}else{page='courses';render();let input=document.getElementById('courseSearch');if(input){input.value=q;filterCourses()}showToast('Đã tìm trong khóa học và bài tập.') }}
function applyTableLabels(root=document){root.querySelectorAll('table.table').forEach(table=>{let headers=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());table.querySelectorAll('tbody tr').forEach(tr=>[...tr.cells].forEach((td,i)=>td.setAttribute('data-label',headers[i]||'')))})}
function render(){if(!sessionUser)return;let ri={name:sessionUser.name,initial:initials(sessionUser.name),label:roleLabel(sessionUser.role)};document.getElementById('sideAvatar').textContent=ri.initial;document.getElementById('topAvatar').textContent=ri.initial;document.getElementById('sideName').textContent=ri.name;document.getElementById('topName').textContent=ri.name;document.getElementById('sideRole').textContent=ri.label;document.getElementById('topRole').textContent=ri.label;document.querySelectorAll('.adminnav').forEach(e=>e.style.display=role==='admin'?'flex':'none');document.querySelectorAll('.nav[data-page]').forEach(e=>{let active=e.dataset.page===page;e.classList.toggle('active',active);if(active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current')});let label={dashboard:'Tổng quan',courses:'Khóa học',assignments:role==='teacher'?'Quản lý bài tập':'Bài tập & kiểm tra',grades:'Bảng điểm',users:'Người dùng',reports:'Báo cáo dữ liệu'}[page]||'Tổng quan';document.getElementById('crumbName').textContent=label;document.getElementById('taskCount').textContent=role==='teacher'?db.assignments.reduce((s,a)=>s+a.submissions.filter(x=>x.score==null).length,0):db.assignments.filter(a=>a.status==='Chưa nộp').length;let target=document.getElementById('content');if(page==='dashboard')target.innerHTML=dashboard();else if(page==='courses')target.innerHTML=coursesPage();else if(page==='assignments')target.innerHTML=assignmentsPage();else if(page==='grades')target.innerHTML=gradesPage();else if(page==='users')target.innerHTML=usersPage();else if(page==='reports')target.innerHTML=reportsPage();applyTableLabels(target);if(page==='reports')loadSqlReports();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav[data-page]').forEach(b=>b.addEventListener('click',()=>{page=b.dataset.page;currentCourse=null;render()}));document.addEventListener('click',e=>{let m=document.getElementById('roleOptions');if(!e.target.closest('.rolemenu')&&!e.target.closest('.profilebtn')){m.classList.remove('open');document.querySelector('.rolemenu>button')?.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){let modal=document.getElementById('modalBack');if(modal.classList.contains('show'))closeModal();let menu=document.getElementById('roleOptions');menu.classList.remove('open');document.querySelector('.rolemenu>button')?.setAttribute('aria-expanded','false')}});
async function loadAuthenticatedApp(user){const stateResponse=await fetch('/api/state',{cache:'no-store',credentials:'same-origin'});const state=await stateResponse.json();if(!stateResponse.ok)throw new Error(state.error||'Không tải được dữ liệu');sessionUser=user;role=user.role;db=state;page='dashboard';currentCourse=null;document.getElementById('loginScreen').hidden=true;document.getElementById('appShell').hidden=false;updateBackendStatus(true,'Đã xác thực · MySQL');render()}
async function login(event){event?.preventDefault();const identifier=document.getElementById('loginIdentifier').value.trim(),password=document.getElementById('loginPassword').value;const button=document.getElementById('loginSubmit'),error=document.getElementById('loginError');error.textContent='';button.disabled=true;button.textContent='Đang đăng nhập…';try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({identifier,password})});const result=await r.json();if(!r.ok)throw new Error(result.error||'Đăng nhập thất bại');await loadAuthenticatedApp(result.user)}catch(e){error.textContent=e.message||'Không thể kết nối máy chủ.'}finally{button.disabled=false;button.textContent='Đăng nhập'}}
async function logout(){try{await fetch('/api/logout',{method:'POST',credentials:'same-origin'})}catch(_){}sessionUser=null;role='student';showLoginScreen('Bạn đã đăng xuất khỏi hệ thống.');document.getElementById('loginIdentifier').value='';document.getElementById('loginPassword').value='Demo123!'}
async function boot(){if(location.protocol!=='http:'&&location.protocol!=='https:'){showLoginScreen('Không mở trực tiếp bằng file://. Hãy chạy start_windows.bat rồi truy cập http://127.0.0.1:8000.');document.getElementById('loginForm').hidden=true;document.querySelector('.demo-title').hidden=true;document.querySelector('.demo-accounts').hidden=true;document.querySelector('.login-footnote').textContent='Backend cục bộ là bắt buộc để xác thực và lưu dữ liệu.';return}try{const r=await fetch('/api/session',{cache:'no-store',credentials:'same-origin'});if(r.ok){const result=await r.json();await loadAuthenticatedApp(result.user);return}showLoginScreen()}catch(e){showLoginScreen('Không kết nối được backend. Hãy chạy start_windows.bat trong thư mục dự án rồi tải lại trang.');document.getElementById('loginForm').hidden=true;document.querySelector('.demo-title').hidden=true;document.querySelector('.demo-accounts').hidden=true;document.getElementById('loginPassword').value='';return}}
boot();
</script>
</body></html>
